typedef struct {
    int r, c;
} Node;

int main(void) {
    int R, C;
    if (scanf("%d %d", &R, &C) != 2) return 0;

    char **g = (char **)malloc(R * sizeof(char *));
    for (int i = 0; i < R; ++i) {
        g[i] = (char *)malloc((C + 5) * sizeof(char));
        scanf("%s", g[i]);
    }

    int pr = -1, pc = -1, er = -1, ec = -1;

    /* Collect soldiers */
    int maxn = R * C;
    Node *q = (Node *)malloc(maxn * sizeof(Node));
    int *distS = (int *)malloc(maxn * sizeof(int));
    int *distP = (int *)malloc(maxn * sizeof(int));

    for (int i = 0; i < maxn; ++i) {
        distS[i] = -1;
        distP[i] = -1;
    }

    int head = 0, tail = 0;

    for (int i = 0; i < R; ++i) {
        for (int j = 0; j < C; ++j) {
            if (g[i][j] == 'a') {
                pr = i; pc = j;
            } else if (g[i][j] == 'r') {
                er = i; ec = j;
            } else if (g[i][j] == 's') {
                q[tail++] = (Node){i, j};
                distS[i * C + j] = 0;
            }
        }
    }

    int dr[5] = {1, -1, 0, 0, 0};
    int dc[5] = {0, 0, 1, -1, 0};

    /* Multi-source BFS for soldiers, including staying put implicitly by time comparison.
       Earliest arrival times to every cell. */
    while (head < tail) {
        Node cur = q[head++];
        int cd = distS[cur.r * C + cur.c];
        for (int k = 0; k < 4; ++k) {
            int nr = cur.r + dr[k];
            int nc = cur.c + dc[k];
            if (nr < 0 || nr >= R || nc < 0 || nc >= C) continue;
            if (g[nr][nc] == '#') continue;
            int id = nr * C + nc;
            if (distS[id] == -1) {
                distS[id] = cd + 1;
                q[tail++] = (Node){nr, nc};
            }
        }
    }

    /* Princess BFS: can move to a cell at time t+1 only if soldiers arrive strictly later,
       because if equal, she is caught. Also start cell must be safe at time 0. */
    if (pr == -1 || er == -1) {
        printf("NO\n");
        return 0;
    }

    if (distS[pr * C + pc] == 0) {
        printf("NO\n");
        return 0;
    }

    head = tail = 0;
    q[tail++] = (Node){pr, pc};
    distP[pr * C + pc] = 0;

    while (head < tail) {
        Node cur = q[head++];
        int t = distP[cur.r * C + cur.c];

        if (cur.r == er && cur.c == ec) {
            printf("YES\n");
            return 0;
        }

        for (int k = 0; k < 5; ++k) {
            int nr = cur.r + dr[k];
            int nc = cur.c + dc[k];
            if (nr < 0 || nr >= R || nc < 0 || nc >= C) continue;
            if (g[nr][nc] == '#') continue;

            int nt = t + 1;
            int id = nr * C + nc;

            if (distP[id] != -1) continue;
            if (distS[id] != -1 && distS[id] <= nt) continue;

            distP[id] = nt;
            q[tail++] = (Node){nr, nc};
        }
    }

    printf("NO\n");
    return 0;
}

