public class PrincessEscape {
    static int R, C;
    static char[][] grid;
    static int[] princessPos;
    static List<int[]> soldiers;
    static int[][] dirs = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}, {0, 0}}; // includes stay
    static int[][] distPrincess, distSoldiers;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        R = sc.nextInt();
        C = sc.nextInt();
        grid = new char[R][C];
        soldiers = new ArrayList<>();
        int[] exit = null;

        for (int i = 0; i < R; i++) {
            String line = sc.next();
            for (int j = 0; j < C; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'P') {
                    princessPos = new int[]{i, j};
                } else if (grid[i][j] == 'S') {
                    soldiers.add(new int[]{i, j});
                } else if (grid[i][j] == 'E') {
                    exit = new int[]{i, j};
                }
            }
        }

        // BFS from princess
        distPrincess = bfs(princessPos[0], princessPos[1]);

        // BFS from all soldiers simultaneously (multi-source BFS)
        distSoldiers = multiBfs(soldiers);

        // Check if princess can reach exit before any soldier
        int pr = exit[0], pc = exit[1];
        if (distPrincess[pr][pc] == -1) {
            System.out.println("No");
            return;
        }

        // If no soldiers, always safe
        if (soldiers.isEmpty()) {
            System.out.println("Yes");
            return;
        }

        // Princess must reach exit strictly before any soldier
        if (distPrincess[pr][pc] < distSoldiers[pr][pc]) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }
    }

    static int[][] bfs(int sr, int sc) {
        int[][] dist = new int[R][C];
        for (int[] row : dist) Arrays.fill(row, -1);
        Queue<int[]> q = new LinkedList<>();
        q.add(new int[]{sr, sc});
        dist[sr][sc] = 0;

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1];
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < R && nc >= 0 && nc < C && grid[nr][nc] != 'W' && dist[nr][nc] == -1) {
                    dist[nr][nc] = dist[r][c] + 1;
                    q.add(new int[]{nr, nc});
                }
            }
        }
        return dist;
    }

    static int[][] multiBfs(List<int[]> sources) {
        int[][] dist = new int[R][C];
        for (int[] row : dist) Arrays.fill(row, -1);
        Queue<int[]> q = new LinkedList<>();

        for (int[] s : sources) {
            int r = s[0], c = s[1];
            if (dist[r][c] == -1) {
                dist[r][c] = 0;
                q.add(new int[]{r, c});
            }
        }

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1];
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < R && nc >= 0 && nc < C && grid[nr][nc] != 'W' && dist[nr][nc] == -1) {
                    dist[nr][nc] = dist[r][c] + 1;
                    q.add(new int[]{nr, nc});
                }
            }
        }
        return dist;
    }
}

