public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c != -1 && c <= ' ');
            if (c == -1) return null;
            while (c != -1 && c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static final int INF = 1_000_000_000;
    static final int[] DR = {-1, 1, 0, 0};
    static final int[] DC = {0, 0, -1, 1};

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        String first = fs.next();
        if (first == null) return;
        int n = Integer.parseInt(first);
        int m = fs.nextInt();

        char[][] grid = new char[n][m];
        int pr = -1, pc = -1, er = -1, ec = -1;
        ArrayDeque<int[]> soldiers = new ArrayDeque<>();

        for (int i = 0; i < n; i++) {
            String s = fs.next();
            while (s.length() < m) s += fs.next();
            for (int j = 0; j < m; j++) {
                char ch = s.charAt(j);
                grid[i][j] = ch;
                if (ch == 'P') {
                    pr = i;
                    pc = j;
                    grid[i][j] = '.';
                } else if (ch == 'E') {
                    er = i;
                    ec = j;
                    grid[i][j] = '.';
                } else if (ch == 'S') {
                    soldiers.add(new int[]{i, j});
                    grid[i][j] = '.';
                }
            }
        }

        int[][] soldierDist = new int[n][m];
        for (int i = 0; i < n; i++) Arrays.fill(soldierDist[i], INF);

        ArrayDeque<int[]> q = new ArrayDeque<>();
        for (int[] pos : soldiers) {
            soldierDist[pos[0]][pos[1]] = 0;
            q.add(pos);
        }

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1];
            int nd = soldierDist[r][c] + 1;
            for (int k = 0; k < 4; k++) {
                int nr = r + DR[k], nc = c + DC[k];
                if (nr < 0 || nr >= n || nc < 0 || nc >= m) continue;
                if (grid[nr][nc] == '#') continue;
                if (soldierDist[nr][nc] > nd) {
                    soldierDist[nr][nc] = nd;
                    q.add(new int[]{nr, nc});
                }
            }
        }

        int[][] princessDist = new int[n][m];
        for (int i = 0; i < n; i++) Arrays.fill(princessDist[i], INF);

        if (0 < soldierDist[pr][pc]) {
            princessDist[pr][pc] = 0;
            q.add(new int[]{pr, pc});
        }

        while (!q.isEmpty()) {
            int[] cur = q.poll();
            int r = cur[0], c = cur[1];
            int t = princessDist[r][c];

            for (int k = 0; k < 4; k++) {
                int nr = r + DR[k], nc = c + DC[k];
                if (nr < 0 || nr >= n || nc < 0 || nc >= m) continue;
                if (grid[nr][nc] == '#') continue;
                int nt = t + 1;
                if (nt >= soldierDist[nr][nc]) continue; // soldier can be there same time or earlier
                if (princessDist[nr][nc] > nt) {
                    princessDist[nr][nc] = nt;
                    q.add(new int[]{nr, nc});
                }
            }

            // staying put is allowed
            int nt = t + 1;
            if (nt < soldierDist[r][c] && princessDist[r][c] > nt) {
                princessDist[r][c] = nt;
                q.add(new int[]{r, c});
            }
        }

        System.out.println(princessDist[er][ec] != INF ? "YES" : "NO");
    }
}

