#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int M, N;
    while (cin >> M >> N) {
        vector<string> grid(M);
        for (int i = 0; i < M; ++i) cin >> grid[i];

        pair<int,int> princess{-1,-1}, exitPos{-1,-1};
        vector<pair<int,int>> soldiers;

        for (int i = 0; i < M; ++i) {
            for (int j = 0; j < N; ++j) {
                if (grid[i][j] == 'P') princess = {i, j};
                else if (grid[i][j] == 'D') exitPos = {i, j};
                else if (grid[i][j] == 'S') soldiers.push_back({i, j});
            }
        }

        const int INF = 1e9;
        vector<vector<int>> distS(M, vector<int>(N, INF));
        queue<pair<int,int>> q;

        for (auto &s : soldiers) {
            distS[s.first][s.second] = 0;
            q.push(s);
        }

        int dr[4] = {-1, 1, 0, 0};
        int dc[4] = {0, 0, -1, 1};

        auto inside = [&](int r, int c) {
            return r >= 0 && r < M && c >= 0 && c < N;
        };

        // Multi-source BFS for soldiers
        while (!q.empty()) {
            auto [r, c] = q.front();
            q.pop();
            for (int k = 0; k < 4; ++k) {
                int nr = r + dr[k], nc = c + dc[k];
                if (!inside(nr, nc)) continue;
                if (grid[nr][nc] == '#') continue;
                if (distS[nr][nc] > distS[r][c] + 1) {
                    distS[nr][nc] = distS[r][c] + 1;
                    q.push({nr, nc});
                }
            }
        }

        vector<vector<int>> distP(M, vector<int>(N, INF));
        queue<pair<int,int>> qp;

        // Princess can only be safe at time 0 if no soldier is already there
        if (distS[princess.first][princess.second] > 0) {
            distP[princess.first][princess.second] = 0;
            qp.push(princess);
        }

        // BFS for princess with safety condition:
        // at time t on a cell, must have t < earliest soldier arrival there
        while (!qp.empty()) {
            auto [r, c] = qp.front();
            qp.pop();

            int t = distP[r][c];
            for (int k = 0; k < 4; ++k) {
                int nr = r + dr[k], nc = c + dc[k];
                if (!inside(nr, nc)) continue;
                if (grid[nr][nc] == '#') continue;
                int nt = t + 1;
                if (nt >= distS[nr][nc]) continue; // soldier can be there same time or earlier
                if (distP[nr][nc] > nt) {
                    distP[nr][nc] = nt;
                    qp.push({nr, nc});
                }
            }
            // staying put is never necessary for improving reachability, so omitted
        }

        if (distP[exitPos.first][exitPos.second] < INF) cout << "Yes\n";
        else cout << "No\n";
    }

    return 0;
}

import sys
from collections import deque

def solve() -> None:
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    n, m = map(int, data[0].split())
    grid = data[1:1+n]

    princess_pos = None
    soldiers = []
    exits = []

    for i in range(n):
        for j in range(m):
            ch = grid[i][j]
            if ch == 'P':
                princess_pos = (i, j)
            elif ch == 'S':
                soldiers.append((i, j))
            elif ch == 'E':
                exits.append((i, j))
            # '#' is wall, '.' is empty

    # If no exit, impossible
    if not exits:
        print("no")
        return

    # BFS from princess to all exits (ignoring soldiers for now)
    # to get minimal steps for princess to reach each exit
    INF = 10**9
    dist_p = [[INF]*m for _ in range(n)]
    dq = deque()
    pi, pj = princess_pos
    dist_p[pi][pj] = 0
    dq.append((pi, pj))
    dirs = [(1,0),(-1,0),(0,1),(0,-1)]
    while dq:
        x, y = dq.popleft()
        for dx, dy in dirs:
            nx, ny = x+dx, y+dy
            if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] != '#':
                if dist_p[nx][ny] > dist_p[x][y] + 1:
                    dist_p[nx][ny] = dist_p[x][y] + 1
                    dq.append((nx, ny))

    # For each soldier, compute BFS distances to all cells
    # Then check if there exists an exit reachable by princess before any soldier
    # We need the minimal distance from any soldier to each cell
    dist_s = [[INF]*m for _ in range(n)]
    dq = deque()
    for sx, sy in soldiers:
        if dist_s[sx][sy] != 0:
            dist_s[sx][sy] = 0
            dq.append((sx, sy))
    while dq:
        x, y = dq.popleft()
        for dx, dy in dirs:
            nx, ny = x+dx, y+dy
            if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] != '#':
                if dist_s[nx][ny] > dist_s[x][y] + 1:
                    dist_s[nx][ny] = dist_s[x][y] + 1
                    dq.append((nx, ny))

    # Check exits: princess must reach strictly before any soldier
    for ex, ey in exits:
        if dist_p[ex][ey] < dist_s[ex][ey]:
            print("yes")
            return
    print("no")

if __name__ == "__main__":
    solve()
